// Custom Worker entry: OpenNext's fetch handler + Cloudflare Cron Triggers.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };

export default {
  fetch: handler.fetch,
  async scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
    const job = event.cron === "0 19 * * *" ? "backup" : "frequent";
    const req = new Request(`https://internal.cron/api/cron?job=${job}`, {
      method: "POST",
      headers: { "x-cron-secret": env.CRON_SECRET ?? "" },
    });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (r: Response) => {
        if (!r.ok) console.error(`[cron:${job}] HTTP ${r.status} ${await r.text()}`);
      }),
    );
  },
};
// Re-export Durable Object classes OpenNext may reference.
// @ts-expect-error generated
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
